import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;
import java.util.stream.Collectors;

class Solution {
    public static String largestNumberFromArray(List<Integer> nums) {
        // Convert integers to strings
        List<String> strNums = new ArrayList<>();
        for (int num : nums) {
            strNums.add(String.valueOf(num));
        }

        // Custom comparator: compare concatenations
        strNums.sort(new Comparator<String>() {
            @Override
            public int compare(String a, String b) {
                String order1 = a + b;
                String order2 = b + a;
                return order2.compareTo(order1);  // Descending order
            }
        });

        // Handle edge case: all zeros
        if (strNums.get(0).equals("0")) {
            return "0";
        }

        // Concatenate sorted strings
        StringBuilder result = new StringBuilder();
        for (String s : strNums) {
            result.append(s);
        }
        return result.toString();
    }

    public static List<String> splitWords(String s) {
        return s.isEmpty() ? List.of() : Arrays.asList(s.split(" "));
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        List<Integer> nums = splitWords(scanner.nextLine()).stream().map(Integer::parseInt).collect(Collectors.toList());
        scanner.close();
        String res = largestNumberFromArray(nums);
        System.out.println(res);
    }
}
